// ProjectSpend is the authz-gated project-wide spend rollup embedded in the repo
// checkpoint-metrics response. Its cost + counts come from the SAME ProjectScope
// Summary that backs GET /projects/{id}/summary (over the request's window), so
// the two surfaces agree. CostUSD is JSON null when no checkpoint in the project
// carried a cost (never a synthetic 0); CostSource collapses the sources, omitted
// when none. RepoCount is the project's repo count in this region.
//
// JSON keys are snake_case to match the enclosing checkpoint-metrics response
// (checkpoint_count, avg_cost_per_checkpoint, …); a camelCase block nested in a
// snake_case object would be inconsistent. Do NOT "fix" to camelCase — CASING-001
// is a confirmed false positive here (see RepoCapabilities for the same rationale).
type ProjectSpend struct {
	ProjectID         string   `json:"project_id"`
	CostUSD           *float64 `json:"cost_usd"`
	CostSource        string   `json:"cost_source,omitempty"`
	CostedCheckpoints int      `json:"costed_checkpoints"`
	TotalCheckpoints  int      `json:"total_checkpoints"`
	RepoCount         int      `json:"repo_count"`
}

// RepoCommitsOutput is entire.io's commits-list envelope (api/src/routes/cache.ts
