// maxCostUSD is the exclusive upper bound the cost columns can hold. They are
// NUMERIC(14,6) — 8 integer digits, 6 fractional — so the largest representable
// value is 99999999.999999; anything >= 1e8 needs a 9th integer digit and
// overflows the column on INSERT.
const maxCostUSD = 1e8

// ValidCostUSD reports whether a parsed cost value is a storable, sane money
// amount: finite (no NaN/Inf, which a broken serialiser can emit and NUMERIC
// can't meaningfully hold), non-negative, and within the NUMERIC(14,6) column
// range (< 1e8). An out-of-range value would pass a mere finite/non-negative
// check yet overflow the column on INSERT, faulting the write and wedging the
// consumer/hydration path in a poison redelivery loop. An invalid value is
// dropped at ingest (the cost goes nil) rather than persisted — again absence
// over garbage.
func ValidCostUSD(v float64) bool {
	return !math.IsNaN(v) && !math.IsInf(v, 0) && v >= 0 && v < maxCostUSD
}

// costUSDScale is the NUMERIC(14,6) column scale: 6 digits after the decimal
// point.
const costUSDScale = 1e6

// RoundCostUSD rounds v to the NUMERIC(14,6) column's 6-decimal-place scale.
// Every cost value that will be both stored in a top-level cost_usd column AND
// carried alongside it in a JSONB breakdown (e.g. per-model buckets) must be
// rounded here BEFORE either write: Postgres rounds a NUMERIC(14,6) column to
// 6dp automatically on INSERT, but a JSONB float64 is stored at full precision,
// so an unrounded value would read back from the column as a different number
// than the same value read from the JSONB — a "why do these two numbers
// disagree" support ticket, and any UI rendering both a total and its
// breakdown would show one that does not add up. Rounding each bucket here
// before summing also means the summed total is the sum of the already-6dp
// parts, so the parts add up to the whole in the JSONB, not just in Postgres.
func RoundCostUSD(v float64) float64 {
	return math.Round(v*costUSDScale) / costUSDScale
}

// SanitizeCost applies the cost invariants to a raw (value, source) pair crossing
// an UNTRUSTED boundary — a cross-cell user_activity_v1 wire event, or egress to a
// peer cell — so it can never fault the cost_source CHECK and poison-loop the
// consumer. A missing or non-finite/negative value is not a storable cost, so the
// whole cost drops (nil/""). A valid value is kept, with its source normalised to
// the pinned vocabulary (an unrecognised label → NULL). Mirrors the inline guards
// in buildCheckpointRow / aggregateSession / mergeSessionTranscript, so every
// persistence boundary agrees.
func SanitizeCost(costUSD *float64, costSource string) (*float64, string) {
	if costUSD == nil || !ValidCostUSD(*costUSD) {
		return nil, ""
	}
	return costUSD, NormalizeCostSource(costSource)
