// mapTokenCounts converts an on-disk token_usage block (snake_case; root,
// per-session, or per-model) to the stored camelCase SessionTokenUsage, carrying
// the token COUNTS only. Cost is not copied here: it is resolved separately per
// bucket by bucketCost — the CLI's reported cost_usd when it carried one (validated
// first, so a garbage value can't reach the column), otherwise the platform
// estimate from these counts. Callers set CostUSD/CostSource on the returned value
// from that result (stamped "reported" or "estimated" accordingly).
func mapTokenCounts(tu tokenUsage) *store.SessionTokenUsage {
	return &store.SessionTokenUsage{
		InputTokens: tu.InputTokens, CacheCreationTokens: tu.CacheCreationTokens,
		CacheReadTokens: tu.CacheReadTokens, OutputTokens: tu.OutputTokens, APICallCount: tu.APICallCount,
	}
}

// applySessionCost sets the session-level cost from the sum of its priced
// per-model buckets. When no bucket priced (every model unknown and none reported
// a cost), the session keeps no cost (nil) — never a synthetic 0. If the session
// carried no aggregate token_usage block yet some bucket priced, a minimal usage
// carrier is created so the checkpoint/rollup sums still capture the cost. The
// session's source is the buckets' distinct labels collapsed to one value: the
// shared label when they agree, "mixed" when a session spans both a CLI-reported
// and a platform-estimated bucket. The summed cost is sanitized to the storable
// NUMERIC(14,6) range (a pathologically large sum drops to nil).
func applySessionCost(si *store.SessionInfo, sum float64, priced bool, sources map[string]struct{}) {
	if !priced {
		return
	}
	if si.TokenUsage == nil {
		si.TokenUsage = &store.SessionTokenUsage{}
	}
	cost, src := store.SanitizeCost(&sum, store.CollapseCostSource(sources))
	si.TokenUsage.CostUSD, si.TokenUsage.CostSource = cost, src
}
