// TestParseSession_Carries1hCacheWriteSplit pins that the 1h-TTL subset of
// cache-creation tokens survives into storage, per model bucket and on the
// session aggregate.
//
// It is stored, not derived, because the re-price job the raw buckets exist for
// (see cost.go) reads these counts back and re-runs pricing.Estimate. A bucket
// that read back CacheCreation1hTokens == 0 would reprice its entire
// cache-creation total at the 5-minute rate (1.25x input) instead of splitting
// out the 1-hour portion (2x input) — a silent underestimate with no error and
// no flag, which is the same failure mode that took the premium out of the CLI's
// own table.
func TestParseSession_Carries1hCacheWriteSplit(t *testing.T) {
	meta := `{"session_id":"s","model":"claude-opus-4-8",
		"token_usage":{"input_tokens":10,"output_tokens":20,"cache_creation_tokens":1000,
			"cache_creation_1h_tokens":400,"cache_read_tokens":5,"api_call_count":1},
		"model_usage":[{"model":"claude-opus-4-8","token_usage":{
			"input_tokens":10,"output_tokens":20,"cache_creation_tokens":1000,
			"cache_creation_1h_tokens":400,"cache_read_tokens":5,"api_call_count":1}}]}`

	ps, ok := parseSession([]byte(meta), []byte("prompt"))
	if !ok {
		t.Fatal("parseSession failed")
	}

	if got := len(ps.Info.ModelUsage); got != 1 {
		t.Fatalf("model_usage buckets = %d, want 1", got)
	}
	bucket := ps.Info.ModelUsage[0].TokenUsage
	if bucket.CacheCreationTokens != 1000 {
		t.Errorf("bucket cache_creation_tokens = %d, want 1000", bucket.CacheCreationTokens)
	}
	if bucket.CacheCreation1hTokens != 400 {
		t.Errorf("bucket cache_creation_1h_tokens = %d, want 400 (the 1h split must reach storage)",
			bucket.CacheCreation1hTokens)
	}

	if ps.Info.TokenUsage == nil {
		t.Fatal("session token_usage missing")
	}
	if ps.Info.TokenUsage.CacheCreation1hTokens != 400 {
		t.Errorf("session cache_creation_1h_tokens = %d, want 400",
			ps.Info.TokenUsage.CacheCreation1hTokens)
	}

	// The stored counts must round-trip through the JSONB encoding the sessions
	// column uses, or the re-price job reads back a different bucket than ingest
	// wrote.
	blob, err := json.Marshal(bucket)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	var back store.SessionTokenUsage
	if err := json.Unmarshal(blob, &back); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	if back.CacheCreation1hTokens != 400 {
		t.Errorf("after JSONB round-trip = %d, want 400", back.CacheCreation1hTokens)
	}
}
GOEOF
