// contributorCountExpr counts distinct contributors in a rad-derived aggregate that
// projects author_account_id + author_github_id: distinct non-null COALESCE(account,
// github id) groups, plus one for the anonymous bucket if any cell has neither.
// External contributors carry a real github_id, so they are counted by id — the list
// and the count key on the same COALESCE(account, github id) and agree (no divergence).
const contributorCountExpr = `count(DISTINCT coalesce(author_account_id::text, 'gh:' || author_github_id::text)) + (count(*) FILTER (WHERE author_account_id IS NULL AND author_github_id IS NULL) > 0)::int`

// costSourceAgg is the SQL twin of the write-side CollapseCostSource: it collapses
// the distinct non-null cost_source values in an aggregate over col to one column
// value — the shared source when they agree, 'mixed' when they disagree, NULL when
// none was labelled (all rows uncosted). min() returns the lone value when exactly
// one distinct source is present. Read into a *string (nil ← NULL → the "" that
// CollapseCostSource yields for none).
//
// min() cannot silently mask a spelling inconsistency (e.g. 'estimated' vs
// 'Estimated'): count(DISTINCT col) is exact-string, case-sensitive matching,
// the same function guarding this branch, so the moment two differently-cased
// rows exist, the count is already 2 and the query takes the 'mixed' branch
// instead — min() only ever runs over a set already known to contain exactly
// one distinct string.
func costSourceAgg(col string) string {
	return `CASE
    WHEN count(DISTINCT ` + col + `) FILTER (WHERE ` + col + ` IS NOT NULL) = 1 THEN min(` + col + `)
    WHEN count(DISTINCT ` + col + `) FILTER (WHERE ` + col + ` IS NOT NULL) > 1 THEN 'mixed'
    ELSE NULL END`
}

// costSourceText resolves a scanned nullable cost_source (nil ← SQL NULL) to the
// store's string form: "" when none, else the collapsed value ("reported" |
// "estimated" | "mixed").
func costSourceText(p *string) string {
	if p == nil {
		return ""
	}
	return *p

