// repoListItem maps a repo store row to the GET /repos item. It fills the
// fields entire-api sources locally (id, full_name, derived name,
// default_branch, checkpoint_count) plus the GitHub metadata joined from
// github_repo_meta (github_id, the GitHub full_name, description, html_url,
// stargazers_count, language, pushed_at→updated_at, and the private/archived
// visibility flags) and the caller's resolved permission tier + capabilities
// (from SpiceDB by the handler). can_manage_access ANDs HoldsManage with
// !r.IsMirror — the store's is_mirror fact, applied here at the wire layer.
func repoListItem(r store.RepoListRow, info auth.RepoAccess) RepoListItem {
	// updated_at maps to GitHub's pushed_at, mirroring entire.io's
	// `pushed_at || synced_at` fallback: whenever pushed_at is absent — no
	// github_repo_meta row, or a row whose nullable pushed_at is null — fall back
	// to the repo row's cached_at (the local analog of synced_at).
	updatedAt := r.CachedAt
	if r.PushedAt != nil {
		updatedAt = *r.PushedAt
	}
	// full_name prefers the GitHub "owner/repo" from github_repo_meta (entire.io's
	// full_name is the GitHub name) and falls back to the repos.full_name → repo_id
	// chain when there's no meta row. The derived name tracks the same resolved
	// human name so the two never disagree.
	humanFull := r.MetaFullName
	if humanFull == "" {
		humanFull = r.FullName
	}
	item := RepoListItem{
		ID:              r.ID,
		GithubID:        r.GithubID, // github_repo_meta.github_repo_id (0 if no meta row)
		FullName:        repoFullNameOr(store.RepoMeta{FullName: humanFull}, r.ID),
		Description:     r.Description,
		HTMLURL:         r.HTMLURL,
		StargazersCount: r.StargazersCount,
