// overviewWindowMax bounds an unbounded (nil) overview `until` at a fixed far
// future, so the ProjectScope Summary — which takes a closed [since, until)
// window — spans all rows when the checkpoint-metrics panel is unbounded (nil
// since ⇒ the zero time as the open lower bound).
var overviewWindowMax = time.Date(9999, 12, 31, 23, 59, 59, 0, time.UTC)

// projectSpend computes the repo's owning-project spend rollup for the request's
// [since, until) window, GATED on the CALLING subject's project.view — the exact
// check GET /projects/{id}/summary runs (checkProjectAccess). It returns nil — the
// handler then OMITS project_spend and still answers 200 — for a repo with no
// owning project, a caller without project access (or no identity, e.g. anonymous),
// or any access-check/store error. That fail-closed omission is what keeps
// project-wide spend from leaking into a repo-only read. The cost + counts come
// from the SAME ProjectScope Summary that backs /projects/{id}/summary (plain
// scope, no payload-visibility narrowing), so the two surfaces agree for an equal
// window — modulo the inclusive-`until` boundary translation below, which aligns
// project_spend with the sibling checkpoint_count in this response and can differ
// from /projects/{id}/summary by at most the single boundary checkpoint.
func projectSpend(ctx context.Context, deps *RepoActivityDeps, repoID string, since, until *time.Time) *ProjectSpend {
	projectID, err := deps.Store.OwningProjectID(ctx, repoID)
	if err != nil || projectID == "" {
		return nil // repo has no owning project, or the lookup failed → omit
	}
	// project_spend is project-wide (cross-repo) spend: only an AUTHENTICATED,
	// non-anonymous caller who affirmatively passes project.view may ever see it.
	// checkpoint-metrics is a publicOp and anonOrRequireAuth attaches the synthetic
	// __anon__ identity for X-Anon-Repo viewers, so auth.FromContext is NON-nil for
	// an anonymous caller — it does not, by itself, exclude one. Exclude the
	// anonymous (and the defensive no-identity) subject explicitly here rather than
	// letting checkProjectAccess evaluate project#view for account:__anon__:
	// AnonSubject is reserved for probing a repo's public_viewer wildcard, never a
	// general permission subject, so a project#view probe with it is the wrong
	// contract and would leak project spend the instant a project ever carried any
	// account:* view grant.
	if id := auth.FromContext(ctx); id == nil || id.IsAnon() {
		return nil // anonymous viewer or no identity → never project-wide data
	}
	ac, err := perRequestAccessChecker(ctx, deps.Reader)
	if err != nil {
		return nil // access-checker build failed → omit, fail-closed
	}
	// The exact project.view point-check GET /projects/{id}/summary gates on. Any
	// non-allow — a 403 deny or a 503 access-system error — omits project_spend
	// (fail-closed): never surfaced on the response, never fails the parent request.
	if err := checkProjectAccess(ctx, ac, projectID); err != nil {
		return nil
	}
	lo := time.Time{}
	if since != nil {
		lo = *since
	}
	hi := overviewWindowMax
	if until != nil {
		// checkpoint_count (CheckpointMetrics) bounds the checkpoint axis INCLUSIVELY
		// (commit_date <= until), but Summary's checkpoint axis is half-open
		// (commit_date < until). Passing `until` raw would drop a checkpoint whose
		// commit lands exactly at `until` from project_spend while it still counts in
		// checkpoint_count — the two numbers in this same response disagreeing at the
		// boundary. commit_date is TIMESTAMPTZ (microsecond-quantized), so advancing
		// the exclusive bound by one microsecond makes `< hi` admit exactly the
		// commit_date == until row and nothing beyond it — identical treatment to the
		// inclusive `<= until` checkpoint_count uses. (This can diverge from
		// /projects/{id}/summary — which windows the same Summary exclusively — by at
		// most the single boundary checkpoint; the scope/visibility parity that keeps
		// project_spend from leaking more than that surface is unchanged.)
		hi = until.Add(time.Microsecond)

