func applySessionCost(si *store.SessionInfo, sum float64, priced bool, sources map[string]struct{}) {
	if !priced {
		return
	}
	if si.TokenUsage == nil {
		si.TokenUsage = &store.SessionTokenUsage{}
	}
	cost, src := store.SanitizeCost(&sum, store.CollapseCostSource(sources))
	si.TokenUsage.CostUSD, si.TokenUsage.CostSource = cost, src
}

