func TestParseSession_FloorsNegativeTokenCounts(t *testing.T) {
	meta := `{"session_id":"s","model":"claude-opus-4-8",
		"model_usage":[{"model":"claude-opus-4-8","token_usage":{
			"input_tokens":-1000000,"output_tokens":1000000,
			"cache_creation_tokens":-5,"cache_creation_1h_tokens":-5,
			"cache_read_tokens":-5,"api_call_count":-1}}]}`

	ps, ok := parseSession([]byte(meta), []byte("prompt"))
	if !ok {
		t.Fatal("parseSession failed")
	}
	require := func(name string, got, want int64) {
		t.Helper()
		if got != want {
			t.Errorf("%s = %d, want %d", name, got, want)
		}
	}
	b := ps.Info.ModelUsage[0].TokenUsage
	require("input", b.InputTokens, 0)
	require("output", b.OutputTokens, 1_000_000)
	require("cache_creation", b.CacheCreationTokens, 0)
	require("cache_creation_1h", b.CacheCreation1hTokens, 0)
	require("cache_read", b.CacheReadTokens, 0)
	require("api_calls", b.APICallCount, 0)

	// And the cost must be priced from the floored counts — output only — rather
	// than letting the negative input discount it.
	if b.CostUSD == nil {
		t.Fatal("bucket should still price from the floored counts")
